// MARK: - Radii, spacing, icons, motion, elevation

public enum Radius {
    public static let lg: CGFloat = 8
    public static let md: CGFloat = 6
    public static let sm: CGFloat = 4
    public static let xl: CGFloat = 10
    public static let xs: CGFloat = 2
    /// Dots and count pills only.
    public static let full: CGFloat = 999
    /// Avatars: 20/24 use `sm`, 32 `md`, 40 and up `lg`.
    public static func avatar(size: CGFloat) -> CGFloat { size <= 24 ? sm : size <= 32 ? md : lg }
}

public enum Space {
    public static let s0_5: CGFloat = 2
    public static let s1: CGFloat = 4
    public static let s10: CGFloat = 40
    public static let s12: CGFloat = 48
    public static let s16: CGFloat = 64
    public static let s2: CGFloat = 8
    public static let s3: CGFloat = 12
    public static let s4: CGFloat = 16
    public static let s5: CGFloat = 20
    public static let s6: CGFloat = 24
    public static let s8: CGFloat = 32
    public static let ringWidth: CGFloat = 2
    public static let ringOffset: CGFloat = 1
}

public enum IconSize {
    public static let md: CGFloat = 20
    public static let sm: CGFloat = 16
    public static let xs: CGFloat = 14
}

/// Desktop's springs (duration and bounce are SwiftUI's own terms).
public enum Motion {
    public static let control = Animation.spring(duration: 0.2, bounce: 0)
    public static let disclosure = Animation.spring(duration: 0.3, bounce: 0)
    public static let overlay = Animation.spring(duration: 0.24, bounce: 0)
    public static let pop = Animation.spring(duration: 0.25, bounce: 0.15)
    public static let press = Animation.spring(duration: 0.1, bounce: 0)
    public static let reflow = Animation.spring(duration: 0.4, bounce: 0)
}

public struct ShadowLayer: Equatable, Sendable {
    public let x: CGFloat, y: CGFloat, blur: CGFloat
    public let color: Color
}

public enum Elevation {
    /// Menus, popovers, tooltips. Prefer the system's own shadows on native sheets and menus.
    public static func popover(dark: Bool) -> [ShadowLayer] { dark ? popoverDark : popoverLight }
    public static func modal(dark: Bool) -> [ShadowLayer] { dark ? modalDark : modalLight }
    static let popoverDark: [ShadowLayer] = [ShadowLayer(x: 0, y: 1, blur: 2, color: Color(hex: 0x0401004D)), ShadowLayer(x: 0, y: 6, blur: 16, color: Color(hex: 0x04010061))]
    static let popoverLight: [ShadowLayer] = [ShadowLayer(x: 0, y: 1, blur: 2, color: Color(hex: 0x04010020)), ShadowLayer(x: 0, y: 6, blur: 16, color: Color(hex: 0x04010029))]
    static let modalDark: [ShadowLayer] = [ShadowLayer(x: 0, y: 2, blur: 6, color: Color(hex: 0x0401004D)), ShadowLayer(x: 0, y: 16, blur: 40, color: Color(hex: 0x04010080))]
    static let modalLight: [ShadowLayer] = [ShadowLayer(x: 0, y: 2, blur: 6, color: Color(hex: 0x04010020)), ShadowLayer(x: 0, y: 16, blur: 40, color: Color(hex: 0x04010036))]
}

// MARK: - Avatars

public enum AvatarStyle {
    /// Ink on every avatar fill.
    public static let ink = Color(hex: 0xFDFAF6FF)
    /// Which of the 8 fills `id` gets: FNV-1a over the UTF-8 bytes, so it matches desktop.
    public static func fillIndex(for id: String) -> Int {
        var h: UInt32 = 0x811c_9dc5
        for b in id.utf8 { h ^= UInt32(b); h = h &* 0x0100_0193 }
        return Int(h % 8)
    }
    public static func fill(for id: String, accent: AccentPreset) -> Color {
        accent.avatarFills[fillIndex(for: id)]
    }
    /// Up to two initials: the first letters of the first two words.
    public static func initials(_ name: String) -> String {
        name.split(whereSeparator: \.isWhitespace).prefix(2).compactMap(\.first).map { String($0).uppercased() }.joined()
    }
}

// MARK: - Theme

/// A `ThemeSpec` resolved for the system appearance: colours, metrics and type, ready to read.
public struct Theme: Equatable, Sendable {
    public let spec: ThemeSpec
    public let isDark: Bool
    public let colors: ThemeColors
    public let metrics: Metrics
    public var type: TypeRamp { metrics.type }
    public var colorScheme: ColorScheme { isDark ? .dark : .light }

    public init(spec: ThemeSpec = ThemeSpec(), systemDark: Bool = true) {
        let dark = spec.appearance.isDark(systemDark: systemDark)
        self.spec = spec
        self.isDark = dark
        self.colors = ThemeColors(packed: DesignLooks.all[spec.lookIndex(dark: dark)])
        self.metrics = Metrics.of(spec.density, spec.textSize)
    }

    public static func == (a: Theme, b: Theme) -> Bool { a.spec == b.spec && a.isDark == b.isDark }

    public static let `default` = Theme()
}

extension EnvironmentValues {
    @Entry public var theme: Theme = .default
}

